import React, { useState } from "react";
import axios from "axios";

export default function CreatePostModal({ close, refreshPosts, user }) {

  const [imagen, setImagen] = useState(null);
  const [descripcion, setDescripcion] = useState("");
  const [cancion, setCancion] = useState("");

  // 🔍 Spotify
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  // 🔥 Subir imagen a Cloudinary
  const subirImagen = async () => {
    if (!imagen) return "";

    const formData = new FormData();
    formData.append("file", imagen);
    formData.append("upload_preset", "naju_upload");

    const res = await fetch(
      "https://api.cloudinary.com/v1_1/dokjayfkn/image/upload",
      {
        method: "POST",
        body: formData
      }
    );

    const data = await res.json();
    return data.secure_url;
  };

  // 🔍 Buscar canción en Spotify
  const buscarCancion = async () => {
    try {
      const res = await axios.get(
        `http://localhost:5000/api/spotify/search?q=${query}`
      );
      setResults(res.data);
    } catch (err) {
      console.error(err);
      alert("Error buscando canciones");
    }
  };

  // 🔥 Crear post
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const imageUrl = await subirImagen();

      const userData = JSON.parse(localStorage.getItem("user"));

      await axios.post("http://localhost:5000/api/posts", {
        user: userData,
        imagen: imageUrl,
        descripcion,
        cancion
      });

      refreshPosts();
      close();

    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || err.message);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">

        <h2>Crear publicación</h2>

        <form onSubmit={handleSubmit}>

          {/* 📷 Imagen */}
          <input
            type="file"
            onChange={(e) => setImagen(e.target.files[0])}
            required
          />

          {/* 📝 Descripción */}
          <input
            type="text"
            placeholder="Descripción"
            value={descripcion}
            onChange={(e) => setDescripcion(e.target.value)}
            required
          />

          {/* 🔍 BUSCADOR SPOTIFY */}
          <input
            type="text"
            placeholder="Buscar canción 🎧"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />

          <button type="button" onClick={buscarCancion}>
            Buscar
          </button>

          {/* 🎵 RESULTADOS */}
          <div style={{ marginTop: 10 }}>
            {results.map((track) => (
              <div
                key={track.id}
                onClick={() => {
                  setCancion(`https://open.spotify.com/embed/track/${track.id}`);
                  setResults([]); // limpiar resultados
                }}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 10,
                  cursor: "pointer",
                  marginBottom: 10
                }}
              >
                <img src={track.album.images[0].url} width={50} />
                <div>
                  <strong>{track.name}</strong>
                  <p style={{ fontSize: 12 }}>
                    {track.artists[0].name}
                  </p>
                </div>
              </div>
            ))}
          </div>

          {/* 🎵 Preview canción */}
          {cancion && (
            <iframe
              src={cancion}
              width="100%"
              height="80"
              frameBorder="0"
              allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture"
            />
          )}

          <button type="submit">Publicar</button>

        </form>

        <button onClick={close}>Cancelar</button>

      </div>
    </div>
  );
}
